/**
 * range(start, end, step = 1): array de números de start (inclusive) até end (exclusive).
 * step pode ser negativo; step 0 lança RangeError.
 */
export function range(start, end, step = 1) {
  if (step === 0) throw new RangeError('step must not be 0');
  const out = [];
  if (step > 0) {
    for (let x = start; x < end; x += step) out.push(x);
  } else {
    for (let x = start; x > end; x += step) out.push(x);
  }
  return out;
}

